/* Zero → AGI glossary: every piece of jargon used across the course, in plain language.
   Consumed by the glossary page in app/js/main.js as window.ZTA.glossary = [{term, def}, ...]. */
(function () {
  const ZTA = (window.ZTA = window.ZTA || {});
  ZTA.glossary = [
    { term: 'Activation function', def: 'A small non-linear function (like ReLU or tanh) applied to a neuron\'s weighted sum before passing it on. Without it, stacking layers would collapse into one big linear function — activations are what let networks learn curved, complex patterns.' },
    { term: 'Adam', def: 'The most widely used optimiser for training neural networks. It keeps a running average of each weight\'s recent gradients and their size, so it can take bigger, more confident steps on some weights and smaller, cautious steps on others.' },
    { term: 'Agent', def: 'An AI system that doesn\'t just answer once but takes a sequence of actions — calling tools, reading results, deciding what to do next — to accomplish a goal. Modern coding assistants and browser-using models are agents built on top of a language model.' },
    { term: 'Alignment', def: 'The broad effort to make an AI system\'s behaviour match what its designers and users actually want, rather than whatever narrow objective it was literally trained on. RLHF, RLVR and constitutional methods are all alignment techniques.' },
    { term: 'Attention', def: 'The mechanism at the heart of the transformer: for every token, it computes how much to "look at" every other token before updating its representation. It lets a model directly connect distant words instead of passing information step by step like an RNN.' },
    { term: 'Autoregressive', def: 'A model that generates output one piece at a time, feeding each piece back in as input to predict the next one. GPT-style language models are autoregressive: they predict the next token given all previous tokens.' },
    { term: 'Backpropagation', def: 'The algorithm that trains neural networks. It runs the chain rule backwards through the network to compute how much each weight contributed to the error, so every weight can be nudged in the direction that reduces the loss.' },
    { term: 'Base model', def: 'A model right after pretraining, before any fine-tuning. It can complete text plausibly but hasn\'t been taught to follow instructions or hold a conversation — that comes later in post-training.' },
    { term: 'Batch', def: 'A group of training examples processed together in one forward/backward pass. Batching lets GPUs do many examples in parallel and gives a smoother, less noisy estimate of the gradient than a single example would.' },
    { term: 'Batch normalization', def: 'A layer that re-centres and re-scales each feature using the mean and variance measured across the current batch, keeping activations in a well-behaved range so deep networks train faster and more reliably. At inference there is no batch to measure, so it falls back on running averages collected during training.' },
    { term: 'Benchmark', def: 'A fixed set of test problems used to measure and compare model capability, such as MMLU for general knowledge or HumanEval for coding. Benchmarks are proxies for real ability, and models can be trained to overfit them.' },
    { term: 'BPE (byte-pair encoding)', def: 'The most common tokenizer training algorithm. It starts with individual characters and repeatedly merges the most frequent adjacent pair into a new token, building up a vocabulary of common word pieces.' },
    { term: 'Chain of thought', def: 'Having a model write out intermediate reasoning steps before its final answer, rather than jumping straight to a conclusion. It reliably improves accuracy on multi-step problems and is the basis of modern "reasoning" models.' },
    { term: 'Chinchilla', def: 'A 2022 DeepMind paper showing that most large language models of the time were undertrained: for a fixed compute budget, a smaller model trained on more data beats a bigger model trained on less. It reset how labs allocate compute between size and data.' },
    { term: 'CLIP', def: 'A model from OpenAI that learns to match images and their text captions in a shared embedding space, trained on hundreds of millions of image-text pairs. It underlies most modern text-to-image and multimodal systems\' sense of "does this picture match this caption."' },
    { term: 'CNN (convolutional neural network)', def: 'A network architecture built from small filters that slide across an image looking for local patterns like edges and textures, stacking into detectors for larger shapes. CNNs dominated computer vision from the 1990s until vision transformers caught up.' },
    { term: 'Context window', def: 'The maximum number of tokens a model can attend to at once — its input plus what it has generated so far. Anything older falls out of view; a bigger context window lets a model use more of a long document or conversation.' },
    { term: 'Cross-entropy', def: 'The standard loss function for classification and language modelling. It measures how surprised the model is by the correct answer — low if the model put high probability on it, high if the model was confident in something else.' },
    { term: 'Diffusion model', def: 'A generative model that learns to reverse a gradual noising process: start from pure noise and repeatedly predict "what noise was added" to denoise it step by step into a coherent image, audio clip, or video. It powers most modern image and video generators.' },
    { term: 'Distillation', def: 'Training a smaller "student" model to mimic a larger "teacher" model\'s outputs (or its full probability distribution, not just the top answer). It compresses most of a big model\'s capability into something cheaper to run.' },
    { term: 'DPO (direct preference optimization)', def: 'A way to train a model on human preference data (A is better than B) without needing a separate reward model or reinforcement learning loop — it directly increases the probability of preferred responses relative to rejected ones.' },
    { term: 'Dropout', def: 'A regularisation trick: during training, randomly switch off a fraction of neurons on each pass, forcing the network to not rely too heavily on any single one. It reduces overfitting and is turned off at inference time.' },
    { term: 'Embedding', def: 'A list of numbers (a vector) that represents a piece of data — a word, an image, a token — as a point in a high-dimensional space, positioned so that similar things end up close together. Almost every deep learning model starts by embedding its input.' },
    { term: 'Embedding table', def: 'The lookup table a model uses to turn each token ID into its embedding vector — literally one row of learned numbers per vocabulary entry. It is one of the first sets of weights a language model learns.' },
    { term: 'Emergence', def: 'A capability that appears suddenly at larger scale rather than improving smoothly — a model that fails a task at every smaller size and then does well past some threshold of parameters or training compute.' },
    { term: 'Encoder / decoder', def: 'Two halves of some architectures: an encoder reads the input into a representation, and a decoder generates output from it (optionally attending back to the encoder). Translation models classically use both; GPT-style models are decoder-only.' },
    { term: 'Epoch', def: 'One complete pass through the entire training dataset. Small datasets might be trained for many epochs; today\'s large language models are typically trained for less than one epoch over a giant corpus.' },
    { term: 'Evals', def: 'Short for evaluations: the suites of tests, benchmarks and graded tasks used to measure a model\'s capabilities, safety and behaviour before and after training changes. "Running evals" is how labs decide whether a change actually helped.' },
    { term: 'Few-shot prompting', def: 'Giving a model a handful of example input-output pairs inside the prompt before asking it to do the task itself, so it can infer the pattern without any weight updates.' },
    { term: 'Fine-tuning', def: 'Continuing to train an already-pretrained model on a smaller, more specific dataset so it specialises for a task, domain, or behaviour — such as following instructions or speaking in a particular style.' },
    { term: 'FLOPs', def: 'Floating-point operations: the standard unit for measuring how much raw computation a training run or a single forward pass used. Total training FLOPs is one of the main knobs in scaling laws.' },
    { term: 'GAN (generative adversarial network)', def: 'A generative model made of two competing networks: a generator that tries to produce fake data and a discriminator that tries to tell fake from real. Training pushes both to improve until the generator\'s outputs are hard to distinguish from genuine data.' },
    { term: 'Gradient', def: 'The direction and rate at which a loss function increases with respect to each weight. Training follows the negative gradient — moving weights the opposite way — to make the loss go down.' },
    { term: 'Gradient descent', def: 'The core training loop: compute the gradient of the loss, take a small step in the direction that reduces it, and repeat. Nearly every neural network is trained by some variant of gradient descent.' },
    { term: 'GRPO (group relative policy optimization)', def: 'A reinforcement-learning method that scores a group of sampled responses to the same prompt against each other (rather than needing a separate learned value function), using the relative ranking to push up better responses. It is central to training modern reasoning models like DeepSeek-R1.' },
    { term: 'GPU', def: 'Graphics processing unit: a chip built to do huge numbers of simple arithmetic operations in parallel. Originally for rendering graphics, GPUs turned out to be ideal for the matrix multiplications neural networks are built from, and they now power almost all AI training.' },
    { term: 'Hallucination', def: 'When a model states something false or fabricated with the same fluent confidence as something true. It happens because the model is generating plausible-sounding text, not looking anything up, so it can produce convincing nonsense.' },
    { term: 'Hidden layer', def: 'Any layer of neurons in a network that sits between the input and the output — its activations are never directly observed, hence "hidden." Depth (more hidden layers) is what makes a network "deep."' },
    { term: 'Hidden state', def: 'The internal memory a recurrent network (or a decoder at a given step) carries forward from one time step to the next, summarising everything relevant it has seen so far.' },
    { term: 'Hyperparameter', def: 'A setting chosen before training begins — learning rate, batch size, number of layers — as opposed to the weights, which are learned during training. Picking good hyperparameters is often its own experimental search.' },
    { term: 'Inference', def: 'Actually running a trained model to get an output, as opposed to training it. Inference is what happens every time you send a prompt to a chatbot.' },
    { term: 'KL divergence', def: 'A measure of how different one probability distribution is from another. In RLHF and DPO it is used to keep a fine-tuned model\'s outputs from drifting too far from a reference model, penalising the policy for straying.' },
    { term: 'KV cache', def: 'During autoregressive generation, the keys and values computed for every previous token are stored so they don\'t have to be recomputed at each new step. It\'s what makes token-by-token generation fast instead of quadratically slow.' },
    { term: 'Latent space', def: 'The compressed, learned representation a model uses internally — a lower-dimensional space where similar inputs land near each other. Diffusion models, VAEs and GANs all generate by manipulating points in a latent space and decoding them back out.' },
    { term: 'Learning rate', def: 'The size of the step gradient descent takes on each update. Too high and training diverges or oscillates; too low and training crawls — much of tuning a model is finding a good learning rate schedule.' },
    { term: 'Logits', def: 'The raw, unnormalised numbers a model outputs just before they are turned into probabilities by a softmax — one number per possible next token or class, where higher means more likely.' },
    { term: 'Loss function', def: 'The single number a model is trained to minimise — how wrong its current predictions are on the training data. Everything about training is choosing a loss function and then reducing it.' },
    { term: 'LoRA (low-rank adaptation)', def: 'An efficient fine-tuning trick that freezes the original model weights and instead trains a pair of small "low-rank" matrices added alongside each layer. It gets most of the benefit of full fine-tuning at a tiny fraction of the memory and compute.' },
    { term: 'LSTM (long short-term memory)', def: 'A recurrent network design from 1997 that adds gates controlling what to remember, forget and output at each step, plus a separate cell state that can carry information over long distances without vanishing. It was the dominant sequence architecture before transformers.' },
    { term: 'MCP (model context protocol)', def: 'An open standard for connecting language models to external tools and data sources — files, APIs, databases — in a consistent way, so any compatible model or app can use any compatible tool without custom glue code for each pair.' },
    { term: 'MFU (model FLOPs utilisation)', def: 'The fraction of a chip\'s theoretical peak compute that a training run actually achieves in practice. Real training runs typically hit 30–50% MFU — the rest is lost to memory movement, communication between chips, and idle time.' },
    { term: 'MLP (multi-layer perceptron)', def: 'The simplest deep network: a stack of fully-connected layers, each neuron connected to every neuron in the previous layer, each followed by an activation function. It\'s the building block used inside transformers as well as a model in its own right.' },
    { term: 'MoE (mixture of experts)', def: 'An architecture where each layer contains many parallel "expert" sub-networks, but a small router only activates a few of them per token. It lets a model have a huge total parameter count while keeping the compute per token much smaller.' },
    { term: 'Multimodal', def: 'A model that can take in and/or produce more than one kind of data — text, images, audio, video — rather than being limited to text alone.' },
    { term: 'Overfitting', def: 'When a model learns the training data too specifically — including its noise and quirks — so it performs well on data it has seen but poorly on new data. Regularisation, dropout and held-out validation sets exist to catch and prevent it.' },
    { term: 'Parameters', def: 'The numbers a model learns during training — weights and biases — as opposed to hyperparameters, which are set beforehand. "A 70-billion-parameter model" means it has 70 billion learned numbers.' },
    { term: 'Perplexity', def: 'A measure of how surprised a language model is by a piece of text, derived from cross-entropy loss. Lower perplexity means the model assigned higher probability to what actually came next — it is a standard way to score language models.' },
    { term: 'Policy', def: 'In reinforcement learning, the strategy an agent follows — a function from states (or prompts) to actions (or responses), usually the thing being trained to maximise reward.' },
    { term: 'Positional encoding', def: 'Since attention alone treats a sequence as an unordered set, transformers add information about each token\'s position in the sequence so the model can tell "the cat sat" from "sat the cat." RoPE is the dominant modern scheme.' },
    { term: 'Post-training', def: 'Everything done to a base model after pretraining to make it useful and safe as an assistant: supervised fine-tuning, RLHF/RLVR, and other alignment steps.' },
    { term: 'PPO (proximal policy optimization)', def: 'A widely used reinforcement-learning algorithm that updates a policy in small, clipped steps so it never changes too drastically in one update — a key ingredient of classic RLHF pipelines.' },
    { term: 'Pretraining', def: 'The first, most expensive stage of training a large language model: predicting the next token over a huge corpus of text (and sometimes other data), with no task-specific labels. It\'s where the model acquires most of its raw knowledge and language ability.' },
    { term: 'Prompt', def: 'The text (and possibly images or other data) given to a model as input, which it conditions its response on. Prompt engineering is the practice of crafting inputs to get better outputs without touching the model\'s weights.' },
    { term: 'Q-learning', def: 'A reinforcement-learning algorithm that learns the expected long-term reward of taking a given action in a given state (its "Q-value"), then acts by picking whichever action has the highest learned value.' },
    { term: 'Quantisation', def: 'Storing a model\'s weights using fewer bits per number (say 4 or 8 bits instead of 16 or 32) to shrink its memory footprint and speed up inference, usually at a small cost in accuracy.' },
    { term: 'RAG (retrieval-augmented generation)', def: 'Having a model search an external document store for relevant passages and insert them into its context before answering, so it can use up-to-date or private information it was never trained on.' },
    { term: 'Regularisation', def: 'Any technique added to training that discourages a model from overfitting — including weight decay, dropout, and early stopping — usually by penalising complexity or noise-fitting rather than the raw prediction error.' },
    { term: 'Reward hacking', def: 'When a model finds a way to score highly on its reward signal without actually doing what its designers wanted — exploiting a loophole in how the reward was measured rather than solving the real task. A famous instance of Goodhart\'s law in AI.' },
    { term: 'Reward model', def: 'A separate model trained to predict how much a human (or a rule) would rate a given response, used as a stand-in reward signal so a policy can be optimised against it at scale via reinforcement learning.' },
    { term: 'RLHF (reinforcement learning from human feedback)', def: 'A post-training pipeline: collect human preferences between candidate responses, train a reward model on those preferences, then use reinforcement learning (classically PPO) to push the language model toward responses the reward model scores highly.' },
    { term: 'RLVR (reinforcement learning from verifiable rewards)', def: 'A post-training approach that skips a learned reward model in favour of automatically checkable rewards — did the code pass its tests, does the final answer match, and so on — which works well for math, coding and other checkable tasks.' },
    { term: 'RNN (recurrent neural network)', def: 'A network that processes a sequence one element at a time, carrying a hidden state forward as memory. It can in principle handle sequences of any length, but plain RNNs struggle to remember anything from many steps ago.' },
    { term: 'RoPE (rotary positional embedding)', def: 'A way of injecting position information by rotating each token\'s query and key vectors by an angle proportional to its position, so the attention score between two tokens naturally depends on their relative distance. It is the positional scheme used by most modern large language models.' },
    { term: 'Sampling', def: 'Choosing the next token from the model\'s predicted probability distribution rather than always taking the single most likely one, which is what makes generated text varied instead of deterministic and repetitive.' },
    { term: 'Scaling laws', def: 'Empirical relationships showing that a model\'s loss decreases smoothly and predictably as you increase parameters, data, and compute together, following roughly a power law. They let researchers forecast a bigger run\'s performance before training it.' },
    { term: 'Self-attention', def: 'Attention applied within a single sequence, where each token attends to every other token in that same sequence (as opposed to attending to a separate sequence, as in encoder-decoder cross-attention).' },
    { term: 'Self-supervised learning', def: 'Training on unlabelled data by constructing the labels automatically from the data itself — like predicting the next word in a sentence, or a masked-out word — so no human annotation is needed at scale.' },
    { term: 'SFT (supervised fine-tuning)', def: 'The first step of post-training: fine-tuning a base model on a curated set of example prompts paired with high-quality responses, so it learns the format and style of being a helpful assistant before any reinforcement learning stage.' },
    { term: 'Softmax', def: 'A function that turns a list of raw numbers (logits) into a probability distribution — all values between 0 and 1, summing to 1 — by exponentiating each and dividing by the total. It\'s the standard final step before sampling a token or reading off a classification.' },
    { term: 'Speculative decoding', def: 'A trick to speed up generation: a small, cheap model guesses several tokens ahead, and the large model verifies them all in one parallel pass, accepting the correct ones — often several tokens for the cost of roughly one.' },
    { term: 'System prompt', def: 'A special instruction given to a model before the user\'s messages, usually invisible to the user, that sets its persona, rules and constraints for the whole conversation.' },
    { term: 'Temperature', def: 'A parameter that controls how random sampling is: low temperature makes the model favour its highest-probability tokens (more deterministic and repetitive), high temperature flattens the distribution (more varied and surprising).' },
    { term: 'Tensor', def: 'A generalisation of scalars, vectors and matrices to any number of dimensions — the basic data structure every deep learning framework computes with. A batch of colour images might be a 4-dimensional tensor: batch × height × width × colour channels.' },
    { term: 'Tokenizer', def: 'The component that converts raw text into a sequence of integer IDs (tokens) a model can process, and converts model output back into text. Modern tokenizers use subword schemes like BPE so both common words and rare ones can be represented.' },
    { term: 'Top-p (nucleus) sampling', def: 'A sampling method that only considers the smallest set of most-likely next tokens whose probabilities add up to some threshold p, then samples among just those — adapting how many options are considered based on how confident the model is.' },
    { term: 'TPU', def: 'Tensor processing unit: a chip Google designed specifically for neural network math, rather than a general-purpose graphics chip repurposed for it like a GPU. TPUs power much of Google\'s own large-scale training and inference.' },
    { term: 'Transformer', def: 'The architecture introduced in 2017 ("Attention Is All You Need") that replaced recurrence with self-attention, letting every token look directly at every other token in parallel. It is the backbone of essentially every modern large language and multimodal model.' },
    { term: 'VAE (variational autoencoder)', def: 'A generative model that learns to compress data into a probabilistic latent space and decode samples from it back into realistic data, trained to balance reconstruction accuracy against keeping that latent space smooth and well-organised.' },
    { term: 'Vanishing gradient', def: 'A failure mode in deep or recurrent networks where the gradient signal shrinks as it is propagated backward through many layers or time steps, until early layers barely learn at all. It is the core problem LSTMs, residual connections and better initialisation were invented to fix.' },
    { term: 'Weight decay', def: 'A regularisation technique that adds a penalty proportional to the square of each weight into the loss, so training prefers smaller weights unless larger ones genuinely reduce error. It is one of the standard defences against overfitting.' },
    { term: 'World model', def: 'An internal representation a system builds of how its environment works, letting it predict the consequences of actions without having to try them all in reality. Whether today\'s large language models have a genuine world model, versus just surface pattern-matching, is a live debate.' },

    { term: 'Action', def: 'In reinforcement learning, a choice an agent can make at a given moment — a move in a game, a token to generate, a motor command — that changes the state of its environment.' },
    { term: 'AI winter', def: 'A period when funding and interest in AI research collapsed after earlier hype failed to deliver, most notably in the 1970s and again in the late 1980s. Each winter followed a wave of over-promising followed by systems that couldn\'t scale to real problems.' },
    { term: 'Anthropic', def: 'The AI safety company that trains the Claude family of models, founded in 2021 by former OpenAI researchers with a focus on making increasingly capable AI systems safe and steerable.' },
    { term: 'Backpropagation through time', def: 'The version of backpropagation used to train recurrent networks: the network is "unrolled" across every time step of a sequence, and gradients flow backward through all of them, which is also why vanishing/exploding gradients are especially severe in RNNs.' },
    { term: 'Bias (in a network)', def: 'An extra learned number added to a neuron\'s weighted sum before the activation function, letting the neuron shift its output up or down independent of its inputs — giving it more flexibility than weights alone.' },
    { term: 'Bias (in data/behaviour)', def: 'Systematic skew in a model\'s outputs that reflects imbalances, stereotypes or gaps in its training data, rather than reflecting the world accurately or fairly.' },
    { term: 'Bigram / trigram', def: 'The simplest possible language models: predicting the next word from just the previous one word (bigram) or previous two words (trigram), by counting how often word sequences occurred in a corpus. They are the historical starting point neural language models improved on.' },
    { term: 'Capability', def: 'What a model can actually do — a specific skill or task it performs well, as measured by evals — as distinct from how it is deployed or aligned.' },
    { term: 'Chain-of-thought prompting', def: 'Explicitly asking a model, via the prompt, to "think step by step" before answering — an early technique for eliciting the reasoning behaviour that later models were directly trained to do by default.' },
    { term: 'Common Crawl', def: 'A free, continuously updated archive of billions of scraped web pages, and one of the largest sources of raw text used to pretrain large language models.' },
    { term: 'Compute', def: 'Shorthand in AI for the total processing power (usually GPU/TPU-hours or FLOPs) used to train or run a model — one of the three ingredients, alongside data and algorithms, that scaling laws track.' },
    { term: 'Constitutional AI', def: 'A training method where a model is guided by a written set of principles (a "constitution") and taught to critique and revise its own responses against them, reducing reliance on large volumes of human-labelled preference data.' },
    { term: 'Decoder-only', def: 'The transformer variant used by GPT-style models: no separate encoder, just a stack of decoder blocks that attend only to earlier tokens and predict the next one, trained purely autoregressively.' },
    { term: 'Deep learning', def: 'The subfield of machine learning that uses neural networks with many stacked layers ("deep" networks) to learn representations directly from raw data, rather than requiring hand-engineered features.' },
    { term: 'Discount factor', def: 'In reinforcement learning, a number between 0 and 1 that shrinks how much future rewards count compared to immediate ones, so an agent doesn\'t treat a reward ten steps away as equal to one it gets right now.' },
    { term: 'Environment', def: 'In reinforcement learning, everything an agent interacts with and receives feedback from — a game, a simulator, or the real world — that responds to the agent\'s actions with new states and rewards.' },
    { term: 'Exploding gradient', def: 'The opposite failure of vanishing gradients: the gradient signal grows uncontrollably large as it propagates backward, causing huge, destabilising weight updates. Gradient clipping is the standard fix.' },
    { term: 'Exploration vs. exploitation', def: 'The core trade-off in reinforcement learning: try something new that might reveal a better strategy (explore), or stick with the best strategy found so far (exploit). Getting this balance right is central to how agents learn efficiently.' },
    { term: 'Fine-tuning dataset', def: 'The curated set of input-output examples used to fine-tune a model — its quality and diversity often matters more than its size, especially for instruction-following.' },
    { term: 'Forward pass', def: 'Running input data through a network to produce an output, as opposed to the backward pass, which computes gradients. Every training step and every inference call includes a forward pass.' },
    { term: 'Foundation model', def: 'A large model trained on broad data at scale that serves as a general-purpose base for many downstream applications, rather than being built for one narrow task.' },
    { term: 'GPT', def: 'Generative Pre-trained Transformer: OpenAI\'s family of decoder-only transformer language models, whose scaling from GPT-1 through GPT-4 and beyond helped define the modern era of large language models.' },
    { term: 'Gradient clipping', def: 'Capping the size of gradients before applying them, to prevent the exploding-gradient problem from causing a destabilising or NaN-producing update.' },
    { term: 'Stochastic gradient descent (SGD)', def: 'Gradient descent that updates weights using the gradient from just one example or a small mini-batch at a time, rather than the whole dataset — trading a noisier gradient estimate for far more frequent, cheaper updates.' },
    { term: 'Hallucination mitigation', def: 'Techniques aimed at reducing confidently-stated falsehoods, including retrieval augmentation, training models to say "I don\'t know," and citation requirements — an open problem with no complete fix yet.' },
    { term: 'Human-in-the-loop', def: 'A system design where a person reviews, corrects or approves a model\'s outputs or decisions rather than letting it act fully autonomously — common in both training (labelling, RLHF) and deployment (approval steps for agents).' },
    { term: 'Interpretability', def: 'The study of what is actually happening inside a trained model — which neurons, circuits or attention patterns represent which concepts — aimed at making these normally opaque systems understandable rather than a black box. In everyday practice the word is also used more simply: a model is interpretable when you can follow its arithmetic from input to decision, as with a weighted sum or a small decision tree.' },
    { term: 'Jailbreak', def: 'A prompt or technique crafted to get a model to bypass its safety training and produce content it was designed to refuse.' },
    { term: 'Key / query / value', def: 'The three vectors attention computes for every token: the query represents what this token is "looking for," the key represents what each token "offers," and the value is what actually gets passed along once attention decides how much to weight it.' },
    { term: 'Layer normalization', def: 'A technique that re-centres and re-scales the activations within each individual training example (rather than across a batch), which is what transformers use in place of batch normalization for training stability.' },
    { term: 'Linear separability', def: 'Whether two classes of data points can be divided by a single straight line (or flat plane in higher dimensions). A single perceptron can only solve linearly separable problems, which is why XOR famously stumped it.' },
    { term: 'Local minimum', def: 'A point in the loss landscape where the loss is lower than every nearby point but not necessarily the lowest possible loss overall — a place gradient descent can get stuck, though in high-dimensional deep networks true bad local minima are rarer than once feared.' },
    { term: 'Logistic regression', def: 'A simple statistical model that predicts a probability by applying a sigmoid function to a weighted sum of inputs — mathematically identical to a single-neuron network with a sigmoid activation, and a common baseline before deep learning.' },
    { term: 'Machine learning', def: 'The broad field of building systems that improve at a task from data and experience rather than from explicitly hand-written rules. Deep learning and neural networks are one major approach within it.' },
    { term: 'Masked language modelling', def: 'A pretraining objective (used by BERT and similar models) where random tokens in a sentence are hidden and the model must predict them from the surrounding context in both directions, as opposed to the strictly left-to-right prediction of autoregressive models.' },
    { term: 'Mixture of experts routing', def: 'The learned gating function inside an MoE layer that decides, per token, which handful of experts to send it to — trained alongside the experts themselves, often with an extra loss term to keep usage balanced across experts.' },
    { term: 'Multi-armed bandit', def: 'A simplified reinforcement-learning setting with no changing state — just a fixed set of options ("arms"), each with an unknown reward distribution — used to study the exploration/exploitation trade-off in its purest form.' },
    { term: 'Multi-head attention', def: 'Running several attention computations in parallel ("heads"), each free to focus on a different kind of relationship between tokens, then combining their outputs — it gives a transformer several independent "perspectives" on the same sequence at once.' },
    { term: 'Neuron', def: 'The basic computational unit of a neural network: it takes a weighted sum of its inputs, adds a bias, and passes the result through an activation function. Networks are built from many neurons arranged in layers.' },
    { term: 'One-hot encoding', def: 'Representing a category as a vector of all zeros except a single 1 in the position for that category — a simple but wasteful alternative to learned embeddings.' },
    { term: 'Open-weight model', def: 'A model whose trained weights are published for anyone to download and run, as opposed to a closed model only accessible through an API — openness of weights is separate from openness of training data or code.' },
    { term: 'Optimizer', def: 'The algorithm that turns computed gradients into actual weight updates — SGD and Adam are the two most common examples, differing in how they use gradient history to adjust step size per weight.' },
    { term: 'Overparameterization', def: 'Having far more parameters than training examples, which classical statistics would predict causes severe overfitting — yet large neural networks trained this way often still generalise well, a still not-fully-explained phenomenon.' },
    { term: 'Perceptron', def: 'The earliest trainable neural network, built by Frank Rosenblatt in 1958: a single artificial neuron that takes a weighted sum of its inputs and fires if the sum crosses a threshold, with a simple rule for adjusting the weights from mistakes. It can only solve linearly separable problems, which is exactly what tripped it up on XOR and helped trigger the first AI winter.' },
    { term: 'Policy gradient (REINFORCE)', def: 'A family of reinforcement-learning methods that skip learning a value table and instead directly adjust a policy\'s action probabilities: nudge up the probability of actions that were followed by high reward, nudge down the ones followed by low reward. REINFORCE is the simplest version; PPO and GRPO are more stable modern descendants.' },
    { term: 'Reasoning model', def: 'A model specifically trained (often via reinforcement learning on verifiable rewards) to produce long chains of intermediate reasoning before its final answer, trading extra inference-time computation for higher accuracy on hard problems.' },
    { term: 'Recurrent connection', def: 'A connection that feeds a layer\'s own previous output back in as part of its next input, which is what gives recurrent networks memory across time steps.' },
    { term: 'Regret (in bandits/RL)', def: 'The gap between the reward an agent actually earned and the reward it could have earned by always picking the best possible option — a way to measure how costly an agent\'s exploration and mistakes were.' },
    { term: 'Reinforcement learning', def: 'A branch of machine learning where an agent learns by trial and error: it takes actions in an environment, receives rewards, and gradually learns a policy that earns more reward over time — no labelled correct answers required.' },
    { term: 'Representation learning', def: 'The idea that a model\'s hidden layers learn to represent data in increasingly useful, abstract ways on their own, rather than being handed pre-designed features — the core promise of deep learning over classical machine learning.' },
    { term: 'Residual connection', def: 'A shortcut that adds a layer\'s input directly to its output, so the layer only has to learn the "difference" from its input rather than the whole transformation from scratch. It is what let networks get dramatically deeper without vanishing gradients (introduced by ResNet, and used throughout transformers).' },
    { term: 'Reward shaping', def: 'Deliberately designing intermediate or partial rewards to guide an agent toward a goal faster, instead of only rewarding final success — done carefully, since a poorly shaped reward is a common cause of reward hacking.' },
    { term: 'Scaling law exponent', def: 'The specific power-law rate at which loss decreases as compute, data, or parameters increase, empirically measured by fitting curves to many training runs at different scales.' },
    { term: 'Sequence-to-sequence', def: 'A model design that maps an input sequence to an output sequence of possibly different length, such as translating one language to another — originally built from an encoder and a decoder, now usually done by decoder-only transformers as well.' },
    { term: 'State', def: 'In reinforcement learning, a complete description of the current situation an agent is in — a board position, a robot\'s sensor readings — that it uses to decide what action to take.' },
    { term: 'State-space model', def: 'A newer family of sequence architectures (like Mamba) that process sequences with a mechanism inspired by control theory, aiming to match transformer quality while scaling more efficiently to very long sequences.' },
    { term: 'Supervised learning', def: 'Training a model on labelled examples — each input paired with the correct output — so it learns to predict the label for new, unseen inputs.' },
    { term: 'Temporal-difference learning', def: 'A reinforcement-learning technique that updates value estimates using the difference between a prediction and a slightly-later, better-informed prediction, rather than waiting for a final outcome — it lets an agent learn from every step, not just the end of an episode.' },
    { term: 'Test-time compute', def: 'Extra computation spent at inference time — like generating a longer chain of thought, or sampling many candidate answers and picking the best — to improve output quality without changing the model\'s weights.' },
    { term: 'Token', def: 'The basic unit a language model reads and generates — usually a word, part of a word, or punctuation mark, produced by a tokenizer. Everything a model does, it does in terms of tokens, not raw characters.' },
    { term: 'Training data', def: 'The dataset a model learns from — its scale, quality, diversity and cleanliness are often as important to final performance as the model\'s architecture or size.' },
    { term: 'Transfer learning', def: 'Taking a model trained on one task or dataset and adapting it to a different but related task, reusing what it already learned instead of starting from scratch — fine-tuning is the most common form of transfer learning today.' },
    { term: 'Validation set', def: 'A portion of data held out from training and used only to check how well a model generalises during development, catching overfitting before it ever reaches an untouched final test set.' },
    { term: 'Value function', def: 'In reinforcement learning, a learned estimate of how much total future reward an agent can expect from a given state (or state-action pair), used to guide which actions look promising.' },
    { term: 'Vision transformer (ViT)', def: 'An adaptation of the transformer architecture to images: an image is cut into a grid of patches, each treated like a token, and processed with the same self-attention machinery used for text.' },
    { term: 'Weights', def: 'The learned numbers that multiply a neuron\'s inputs before they are summed — along with biases, weights are what training actually changes, and what "training a model" ultimately means: finding good values for millions or billions of them.' },
    { term: 'Zero-shot / few-shot', def: 'Zero-shot means asking a model to perform a task with no examples at all, relying on its general training; few-shot means giving it a handful of examples in the prompt first. Both work without ever updating the model\'s weights.' },
    { term: 'Goodhart\'s law', def: '"When a measure becomes a target, it ceases to be a good measure." In AI it explains why optimising hard against a proxy reward or benchmark tends to find loopholes rather than genuinely improving at the underlying goal.' },
    { term: 'Credit assignment problem', def: 'The challenge of figuring out which of many earlier actions deserves credit or blame for a reward received much later — central to why reinforcement learning over long sequences is hard.' },
    { term: 'Domain randomisation', def: 'Deliberately varying simulated training conditions (lighting, physics, textures) so a policy trained in simulation generalises to the messier real world instead of overfitting to one exact simulated setup.' },
    { term: 'ε-greedy', def: 'A simple exploration strategy: act greedily (pick the currently best-known action) most of the time, but with small probability ε pick a random action instead, to keep discovering potentially better options.' },
    { term: 'UCB (upper confidence bound)', def: 'An exploration strategy that picks the action with the highest "optimistic" estimate of reward — its average observed reward plus a bonus for how uncertain that estimate still is — automatically favouring under-tried options.' },
    { term: 'Bottleneck problem (seq2seq)', def: 'The limitation of early encoder-decoder models: the entire input sequence had to be squeezed into one fixed-size vector before the decoder could use it, losing detail on long inputs — attention was invented specifically to remove this bottleneck.' },
    { term: 'GRU (gated recurrent unit)', def: 'A simplified alternative to the LSTM with fewer gates and no separate cell state, often achieving similar performance with less computation.' },
    { term: 'QLoRA', def: 'A combination of quantisation and LoRA that fine-tunes a model whose frozen weights are compressed to very low precision, dramatically cutting the memory needed to fine-tune large models on modest hardware.' },
    { term: 'Linear attention', def: 'Variants of attention that approximate the standard mechanism using operations that scale linearly rather than quadratically with sequence length, trading some accuracy for the ability to handle much longer sequences efficiently.' },
    { term: 'Neural language model', def: 'A language model built from a neural network (rather than simple word-frequency counting like a bigram model), able to generalise to word sequences it never saw during training by learning distributed representations of words.' },
    { term: 'Scorecard', def: 'A structured summary of how a model performed across a set of evaluations, used internally to compare model versions before deciding whether to ship one.' },
    { term: 'Side effect (RL/alignment)', def: 'An unintended consequence of an agent pursuing its given objective — changes to the environment or its behaviour that nobody wanted but that weren\'t explicitly penalised, a recurring concern in AI safety.' },
    { term: 'Dot product', def: 'Multiply two lists of numbers pair by pair and add up the results. It is how a neuron weighs its inputs, how two embeddings are compared, and how attention scores a match: the single most common operation in AI.' },
    { term: 'Chain rule', def: 'How slopes combine through a chain of steps: multiply them. If nudging a changes b by 3× and nudging b changes c by 2×, nudging a changes c by 6×. Backpropagation is this rule applied to every weight at once.' },
    { term: 'Saddle point', def: 'A spot on the loss surface that is flat but is not a minimum: it curves up in some directions and down in others. In very high dimensions these are far more common than true local minima.' },
    { term: 'Underfitting', def: 'A model too simple (or trained too little) to capture the pattern, so it does badly even on the data it was trained on. The opposite failure to overfitting.' },
    { term: 'Training set', def: 'The examples the model actually learns from. Its score on these says little, because it has seen the answers.' },
    { term: 'Test set', def: 'Examples held back and used once, at the very end, to measure how the model does on data it has never seen and that no decision was tuned on.' },
    { term: 'Momentum', def: 'An optimiser trick: keep a running average of recent gradients and move along that instead of the latest one. Steps in a consistent direction build up speed; jitter cancels out.' },
    { term: 'AdamW', def: 'Adam with weight decay applied correctly, as a separate shrink of the weights. The default optimiser for training transformers.' },
    { term: 'Mini-batch', def: 'A small random handful of training examples (often 32 to a few thousand) used to estimate the gradient for one update, instead of the whole dataset.' },
    { term: 'Accuracy', def: 'The share of predictions that are right. Misleading on its own whenever one answer is much more common than the other.' },
    { term: 'Precision', def: 'Of everything the model flagged, the share that really was what it said. High precision means few false alarms.' },
    { term: 'Recall', def: 'Of everything that should have been flagged, the share the model actually caught. High recall means few misses.' },
    { term: 'Filter (kernel)', def: 'A small grid of weights, typically 3×3, slid across an image. At each position it is multiplied against the pixels beneath and summed, so it responds strongly wherever its pattern appears.' },
    { term: 'Feature map', def: 'The grid of numbers a filter produces as it slides over an image: a map of where that filter\'s pattern was found.' },
    { term: 'Stride', def: 'How many pixels a filter moves between positions. A stride of 2 skips every other position and halves the output size.' },
    { term: 'Padding', def: 'Extra border pixels (usually zeros) added around an image so a filter can be centred on the edge pixels and the output keeps its size.' },
    { term: 'Pooling', def: 'Shrinking a feature map by summarising each small block with one number. Max pooling keeps the largest value in each block.' },
    { term: 'Receptive field', def: 'The patch of the original input that can influence one unit deep in a network. It grows with every layer, which is how deep units come to see whole objects.' },
    { term: 'ReLU', def: 'The simplest popular activation function: pass positive numbers through unchanged and turn negatives into zero.' },
    { term: 'ResNet', def: 'A 2015 network design that adds shortcut connections around blocks of layers, which made networks hundreds of layers deep trainable. See residual connection.' },
    { term: 'Cell state', def: 'The LSTM\'s long-term memory: a channel that runs along the whole sequence and is changed only by gates, so information and gradients can survive hundreds of steps.' },
    { term: 'Gate', def: 'In an LSTM or GRU, a learned dial between 0 and 1 that decides how much of something to let through: what to forget, what to write, what to reveal.' },
    { term: 'Cosine similarity', def: 'How closely two vectors point in the same direction, ignoring their lengths: 1 is the same direction, 0 is unrelated, −1 is opposite. The standard way to compare embeddings.' },
    { term: 'Distributional hypothesis', def: 'The idea that a word\'s meaning is captured by the company it keeps: words that appear in similar contexts mean similar things. The foundation of word embeddings.' },
    { term: 'Skip-gram', def: 'The word2vec training task: given a word, predict the words that appear near it. Solving it forces similar words to get similar vectors.' },
    { term: 'Contextual embedding', def: 'A vector for a word as used in one particular sentence, so "bank" by a river and "bank" with money get different vectors. Transformers produce these.' },
    { term: 'Vector database', def: 'A store of embeddings that can quickly find the ones nearest to a query vector. The retrieval half of RAG.' },
    { term: 'PCA', def: 'Principal component analysis: a way to flatten many-dimensional data to two or three dimensions for plotting, keeping the directions along which the data varies most.' },
    { term: 'Causal masking', def: 'Blocking each position in a transformer from attending to later positions, so that it cannot peek at the tokens it is being trained to predict.' },
    { term: 'Autoencoder', def: 'A network trained to squeeze its input through a narrow middle and reconstruct it. The middle becomes a compact description of the input.' },
    { term: 'Mode collapse', def: 'A GAN failure where the generator finds a few outputs that fool the discriminator and produces only those, ignoring the variety in the real data.' },
    { term: 'Classifier-free guidance', def: 'A diffusion trick: compute the denoising step with and without the text prompt, then push further in the direction the prompt adds. Higher guidance follows the prompt more closely at the cost of variety.' },
    { term: 'Latent diffusion', def: 'Running diffusion in a VAE\'s small compressed space instead of on raw pixels, then decoding the result. It is what made image generation affordable.' },
    { term: 'Flow matching', def: 'A successor to diffusion training: learn the velocity that carries noise straight to data along a simple path, which needs fewer sampling steps.' },
    { term: 'Cross-attention', def: 'Attention where one sequence looks at a different one, for example an image being generated looking at the words of its prompt.' },
    { term: 'Reward', def: 'The number an environment hands an RL agent after an action, saying how good that outcome was. The agent\'s whole goal is to collect as much of it as possible over time.' },
    { term: 'Off-policy', def: 'Learning about one way of behaving from data collected while behaving another way. Q-learning is off-policy: it learns the best policy while still exploring at random.' },
    { term: 'Advantage', def: 'How much better an action turned out than the average for that situation. Policy-gradient methods reinforce actions in proportion to it.' },
    { term: 'Actor–critic', def: 'An RL design with two parts: an actor that chooses actions and a critic that estimates how good situations are, so the actor gets a steadier learning signal.' },
    { term: 'Teacher forcing', def: 'Training a sequence model by always feeding it the true previous tokens rather than its own guesses, so every position can be trained at once.' },
    { term: 'Instruction tuning', def: 'Fine-tuning a base model on examples of instructions paired with good responses, so it answers a request instead of merely continuing the text.' },
    { term: 'Chat template', def: 'The fixed markers a model was trained with to separate system, user and assistant turns. Using the wrong one quietly degrades a model.' },
    { term: 'RLAIF', def: 'Reinforcement learning from AI feedback: like RLHF, but the preference judgements come from a model following written principles instead of from people.' },
    { term: 'Red-teaming', def: 'Deliberately attacking a model to find the inputs that make it misbehave, before someone else does.' },
    { term: 'Contamination', def: 'When benchmark questions have leaked into a model\'s training data, so its score measures memory rather than ability.' },
    { term: 'Greedy decoding', def: 'Always picking the single most likely next token. Deterministic, and prone to dull or repetitive text.' },
    { term: 'Top-k sampling', def: 'Sampling the next token from only the k most likely candidates, discarding the long tail.' },
    { term: 'Function calling (tool use)', def: 'Letting a model reply with a structured request to run a named function, whose result is handed back to it. It is how a model reaches calculators, search, databases and code.' },
    { term: 'Prompt caching', def: 'Storing the model\'s internal work on a prompt prefix so that repeated requests sharing it are faster and much cheaper.' },
    { term: 'Structured output', def: 'Constraining a model\'s sampling so its reply is guaranteed to fit a format such as a JSON schema.' },
    { term: 'Computer use', def: 'A model operating software the way a person does: looking at screenshots and issuing clicks and keystrokes.' },
    { term: 'Harness', def: 'The ordinary program around a model that turns it into an agent: it runs the loop, executes tool calls, manages the context and decides when to stop.' },
    { term: 'Time horizon', def: 'METR\'s measure of agent capability: the length of task, in human working time, that a model completes successfully half the time.' },
    { term: 'Scalable oversight', def: 'Research into how humans, or weaker trusted systems, can reliably check the work of a system more capable than they are.' },
    { term: 'Synthetic data', def: 'Training data generated by a model or a simulator instead of collected from people, usually filtered or verified before use.' },
    { term: 'Calibration', def: 'Whether stated confidence matches reality: of the things a model says it is 80% sure of, about 80% should be true.' },
    { term: 'Transformative AI', def: 'AI whose effect on the world is comparable to the agricultural or industrial revolution. A definition by consequences, where "AGI" is a definition by abilities.' },
    { term: 'tanh', def: 'An activation function that squashes any number into the range −1 to 1, with 0 staying at 0.' },
    { term: 'Decision tree', def: 'A model that is a stack of yes/no questions, each about one column; every path ends in a box that gives a verdict.' },
    { term: 'Leaves', def: 'The final boxes of a decision tree, where no more questions are asked; each votes with its majority.' },
    { term: 'Split', def: 'One cut in a decision tree: a single question about one column that divides a box in two.' },
    { term: 'Entropy', def: 'The average surprise in a group, in bits. Zero for a group of one kind, one bit for a half-and-half mix.' },
    { term: 'Information gain', def: 'How far a split lowers entropy: entropy before, minus the size-weighted entropy of the two new boxes. A tree takes the split with the highest gain.' },
    { term: 'Gini impurity', def: 'An alternative to entropy with cheaper arithmetic: one minus the squared share of each class.' },
    { term: 'Greedy', def: 'Taking the best-looking step right now without looking ahead or revisiting earlier choices. It is how a tree picks its cuts.' },
    { term: 'Pruning', def: 'Growing a full decision tree and then removing the branches that do not earn their keep on held-out data.' },
    { term: 'Bootstrap sample', def: 'A sample the same size as the data, drawn from it with replacement, so some rows repeat and about a third are left out.' },
    { term: 'Bagging', def: 'Training many models on different bootstrap samples and letting them vote or average.' },
    { term: 'Random forest', def: 'Many deep decision trees, each grown on a different bootstrap sample and allowed only a few randomly chosen columns per cut; the forest answers by majority vote.' },
    { term: 'Residuals', def: 'What the model so far still gets wrong: the true value minus the current prediction, for each example.' },
    { term: 'Boosting', def: 'Building a model as a sequence of small models, each fitted to correct the errors left by those before it.' },
    { term: 'Stump', def: 'The smallest possible tree: one cut and two output values.' },
    { term: 'Gradient boosting', def: 'Boosting in which each new tree is fitted to the negative gradient of the loss (for squared error, the residuals). The family behind XGBoost and LightGBM, and still the usual winner on tables of data.' },
    { term: 'k-nearest neighbours', def: 'A method with no training step: to judge a new example, find the k closest stored examples and report their majority.' },
    { term: 'k-means', def: 'A label-free grouping method: every point joins its nearest centre, every centre moves to the average of its points, and this repeats until nothing moves. The result depends on where the centres start.' },
    { term: 'Cluster', def: 'A group of points an algorithm has put together because they are close; a suggestion to go and look, not a finding by itself.' },
    { term: 'Linear regression', def: 'Predicting a number with w·x + b, the weight and bias chosen to make the squared misses as small as possible.' },
    { term: 'Least squares', def: 'Choosing a model\'s numbers to minimise the sum of squared differences between its predictions and the true values.' },
    { term: 'Tabular data', def: 'Data arranged as a table, one row per case and one column per fact about it. Most business data has this shape.' },
    { term: 'Learning curve', def: 'A chart of a model\'s score on unseen data against how much training data it was given. It shows whether more data or a different model is the fix.' },
    { term: 'Bias–variance trade-off', def: 'A model misses partly through bias (what it cannot express, however much data it gets) and partly through variance (how much it changes with the sample it learned from). With a fixed amount of data, reducing one tends to raise the other.' },
    { term: 'Baseline', def: 'The score of the laziest method that could possibly work, measured before any model. A model is worth only what it adds on top.' },
    { term: 'Majority class', def: 'The commoner of the possible answers. Always guessing it is the standard baseline for a yes/no question.' },
    { term: 'Black box', def: 'A model whose internal numbers are all visible but none of them reads as a reason. You learn what it does only by probing it from outside.' },
    { term: 'Latency', def: 'The time from a request arriving to its answer being returned.' },
    { term: 'Latency budget', def: 'The longest a product can tolerate waiting for an answer, usually promised as a percentile (for example "95% of replies under 800 ms") and shared among every step a request passes through.' },
    { term: 'Cascade', def: 'A cheap model answers everything it is confident about and passes the rest to an expensive one. It cuts cost, but hard cases are as slow as the expensive model.' },
    { term: 'Labelling guideline', def: 'The written rule labellers follow so that everyone means the same thing by each label. It grows a new clause each time labellers split on a case.' },
    { term: 'Adjudication', def: 'Sending an item labellers disagreed on to a senior person who decides. The ruling usually becomes a new line in the guideline.' },
    { term: 'Inter-annotator agreement', def: 'How consistently different people give the same label to the same items. Low agreement means the task or its guideline is unclear.' },
    { term: 'Cohen\'s kappa', def: 'Agreement between two labellers beyond what chance would give: (observed − chance) ÷ (1 − chance). 1 is perfect, 0 is no better than luck.' },
    { term: 'Label noise', def: 'Wrong labels in a dataset. Random mistakes largely cancel given enough data; one-sided mistakes push the model the same way every time.' },
    { term: 'Data leakage', def: 'Information reaching a model in training that it will not have when it is used, such as a column filled in after the outcome was known. It produces a brilliant test score that collapses in use.' },
    { term: 'Group split', def: 'Cutting train and test so that every member of a group (all one customer\'s tickets, all one patient\'s scans) sits wholly on one side.' },
    { term: 'Time split', def: 'Training on earlier data and testing on the most recent, so the test resembles how the future will arrive.' },
    { term: 'Class imbalance', def: 'When one answer vastly outnumbers the other. Accuracy can look high while the model misses most of the rare cases.' },
    { term: 'Downsampling', def: 'Throwing away examples of the common class until the training pile is balanced. It shifts the model\'s cut-off: more rare cases caught, more false alarms.' },
    { term: 'Near-duplicates', def: 'Items that are the same for practical purposes but differ by a few characters, so exact matching misses them. Left in, they can put the same example on both sides of a split.' },
    { term: 'Data versioning', def: 'Keeping an identifier for every version of the data, labels, guideline and split, and recording which ones each model was built from.' },
    { term: 'Datasheet', def: 'A short document shipped with a dataset describing its origin, contents, labelling and limits.' },
    { term: 'Paired comparison', def: 'Scoring two versions on the very same items and looking at the gap, so the luck of which items were drawn cancels. Only items where the two versions disagree carry information.' },
    { term: 'Held-out set', def: 'A part of the eval set you never read item by item and never tune on, scored only before a release, so its score is not inflated by picking the luckiest of many tries.' },
    { term: 'Slice', def: 'The eval score on one tagged subgroup of items (a topic, a language). It exposes failing groups hidden by the average, and is itself a small eval set with a wide interval.' },
    { term: 'Offline evaluation', def: 'Scoring a model on a fixed set of questions before any user is involved. Fast and repeatable, but it only measures what your set and answer key contain.' },
    { term: 'Online evaluation', def: 'Measuring what real users do with the live product, such as thumbs-up rate or repeat contact.' },
    { term: 'A/B test', def: 'An online experiment that splits users at random between the old version and the new one and compares a behaviour. Random assignment stops either group being systematically given the easier crowd.' },
    { term: 'Peeking', def: 'Checking a running A/B test repeatedly and stopping the first time it looks significant. Each look is another chance for noise to cross the line, which multiplies false wins.' },
    { term: 'Regression', def: 'A change that breaks something which used to work. (In statistics the same word means fitting a line to predict a number; see linear regression.)' },
    { term: 'Regression suite', def: 'A set of cases that must keep passing, rerun on every change and read case by case. Every bug a user reports becomes a new case.' },
    { term: 'Rubric', def: 'A written checklist that turns "is this answer good?" into several narrow questions that different markers answer the same way.' },
    { term: 'LLM-as-judge', def: 'Using a strong language model to mark answers against a rubric. Fast and cheap, but the judge has biases of its own and must be checked against human labels.' },
    { term: 'Position bias', def: 'A judge\'s tendency to favour an answer because of where it is shown, for example first. Exposed by swapping the order.' },
    { term: 'Verbosity bias', def: 'A judge\'s tendency to favour the longer, more confident-sounding answer regardless of correctness. Swapping the order does not remove it.' },
    { term: 'Self-preference', def: 'A judge model\'s tendency to rate text from its own model family above other text of equal quality.' },
    { term: 'Utilisation', def: 'The fraction of time a server spends working: arrivals per second divided by what it can clear per second.' },
    { term: 'Autoscaling', def: 'A program that adds servers when traffic climbs and removes them when it falls, to keep utilisation at a level with headroom.' },
    { term: 'Percentile', def: 'Sort every measurement from smallest to largest; the pth percentile is the value p% of the way along. p50 is the median; p99 is the value only one request in a hundred exceeds.' },
    { term: 'Tail', def: 'The slow end of the latency distribution: the few requests that take far longer than the typical one.' },
    { term: 'Throughput', def: 'How many requests a system answers per second.' },
    { term: 'Batching', def: 'Answering several requests in one pass through the model. It raises throughput and lowers cost per request, at the price of each request waiting for its batch.' },
    { term: 'Response cache', def: 'A store of past answers handed to the next person who asks the same thing, with no model call. Fast and nearly free, but answers can go stale or reach the wrong user.' },
    { term: 'Router', def: 'A component that looks at each request and picks which model answers it, sending easy requests to a small cheap model and hard ones to a large one.' },
    { term: 'Rate limit', def: 'A cap on how many requests one user or key may send in a period. It protects the bill and stops one heavy user from slowing everyone.' },
    { term: 'Alert', def: 'A rule that notifies a person when a monitored number crosses a line. A sensitive rule gives false alarms; a calm one notices late.' },
    { term: 'Drift', def: 'The data a model meets in production moving away from the data it was trained on, so a frozen model gets worse with no change to its code.' },
    { term: 'Canary release', def: 'Sending a small share of traffic to a new version first and comparing it live against the old one, so a bad release hurts few users.' },
    { term: 'Rollback', def: 'Putting the previous version back with one command. It needs the old model, prompt and configuration kept and versioned together.' },
    { term: 'Timeout', def: 'A limit on how long to wait for a call before giving up, so a hung call cannot hold a user indefinitely.' },
    { term: 'Retry', def: 'Sending a failed call again. It turns a rare failure into a rarer one, but in an outage it multiplies load, so retries are spaced out and capped.' },
    { term: 'Fallback', def: 'The answer given when the best one is unavailable: a smaller model, a cached reply, or an honest message.' },
    { term: 'Guardrails', def: 'Checks around a model: before the call, on whether the request is in scope and safe; after it, on whether the output is well-formed and safe to show.' },
    { term: 'Feedback loop', def: 'The cycle in which production logs, user reactions and incidents become new training data and test cases for the next model.' },
  ];
})();
